#pragma once

#include <llvm/MC/MCInstPrinter.h>

#include <cstdint>
#include <utility>

namespace llvm
{
    class InkVMInstPrinter : public MCInstPrinter
    {
        public:
            InkVMInstPrinter(const MCAsmInfo& MAI, const MCInstrInfo& MII, const MCRegisterInfo& MRI)
                : MCInstPrinter(MAI, MII, MRI)
            {
            }

            void printRegName(raw_ostream& OS, MCRegister Reg) override;
            void printInst(const MCInst* MI, uint64_t Address, StringRef Annot, const MCSubtargetInfo& STI, raw_ostream& OS) override;

            // Generated by llvm-tblgen -gen-asm-writer.
            std::pair<const char*, uint64_t> getMnemonic(const MCInst& MI) const override;
            void printInstruction(const MCInst* MI, uint64_t Address, raw_ostream& OS);
            static const char* getRegisterName(MCRegister Reg);

        private:
            void printOperand(const MCInst* MI, unsigned OpNo, raw_ostream& OS);
            void printMemOperand(const MCInst* MI, unsigned OpNo, raw_ostream& OS);
            void printSymbolOperand(const MCInst* MI, unsigned OpNo, raw_ostream& OS);
            void printSymMemOperand(const MCInst* MI, unsigned OpNo, raw_ostream& OS);
    };
} // namespace llvm
